insert into public.culture_members (
  organization_id, name, name_kk, name_ru, role_kk, role_ru,
  education_kk, education_ru, specialty_kk, specialty_ru,
  level_kk, level_ru, has_higher_education, images, sort_order, is_active
)
select org.id, i.name, i.name_kk, i.name_ru, i.role_kk, i.role_ru,
       i.education_kk, i.education_ru, i.specialty_kk, i.specialty_ru,
       i.level_kk, i.level_ru, i.has_higher_education, i.images, i.sort_order, true
from incoming i cross join org
where not exists (
  select 1 from public.culture_members m where m.organization_id = org.id
);

commit;
